# ============================================================
# EXCEL / COLUMN HELPERS
# ============================================================
def _norm(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value).strip().lower()).strip()


def detect_header_row(raw_preview):
    for idx, row in raw_preview.iterrows():
        vals = {_norm(v) for v in row.tolist() if pd.notna(v)}
        if (
            "country" in vals
            and any(v in vals for v in ["s2e e2e name", "e2e name", "e2e"])
            and any(v in vals for v in ["test set name", "test set id"])
            and "test id" in vals
        ):
            return int(idx)
    return None


def load_source_workbook(file_like):
    file_like.seek(0)
    xls = pd.ExcelFile(file_like)

    for sheet in xls.sheet_names:
        preview = pd.read_excel(xls, sheet_name=sheet, header=None, nrows=20)
        if preview.empty:
            continue
        header_row = detect_header_row(preview)
        if header_row is not None:
            df = pd.read_excel(xls, sheet_name=sheet, header=header_row)
            return df, sheet, header_row

    raise ValueError(
        "Could not find a worksheet containing Country, E2E, Test Set and Test ID headers."
    )


def find_column(df, candidates):
    normalized = {_norm(c): c for c in df.columns}
    for candidate in candidates:
        key = _norm(candidate)
        if key in normalized:
            return normalized[key]

    for c in df.columns:
        c_norm = _norm(c)
        for candidate in candidates:
            cand = _norm(candidate)
            if cand and cand in c_norm:
                return c
    return None


def standardize_input(df_raw):
    mapping = {}
    missing = []

    for standard_name, candidates in REQUIRED_COLUMNS.items():
        found = find_column(df_raw, candidates)
        if found is None:
            missing.append(standard_name)
        else:
            mapping[found] = standard_name

    if missing:
        raise ValueError(f"Missing required columns: {', '.join(missing)}")

    optional_candidates = {
        "E2EID": ["e2e_id", "e2e id"],
        "TestSetFolderID": ["test set folder id", "test_set_folder_id"],
    }
    for standard_name, candidates in optional_candidates.items():
        found = find_column(df_raw, candidates)
        if found is not None:
            mapping[found] = standard_name

    base = df_raw[list(mapping.keys())].rename(columns=mapping).copy()

    for c in base.columns:
        base[c] = base[c].where(base[c].notna(), "")
        base[c] = base[c].astype(str).str.strip()
        base[c] = base[c].replace({"nan": "", "None": ""})

    base = base[(base["Country"] != "") & (base["E2EName"] != "")].copy()
    return base


# ============================================================
# COUNTRY / GENERAL-E2E LOGIC
# ============================================================
def extract_e2e_country_code(e2e_name):
    """
    Examples:
      E2E_DP4_DE_0218_... -> DE
      E2E_DP4_GT_0021_... -> GT  (general E2E)
      E2E_FAO_AT_0499_... -> AT
    """
    s = str(e2e_name).strip()
    m = re.match(r"^E2E_[^_]+_([A-Za-z]{2,4})_", s, flags=re.IGNORECASE)
    return m.group(1).upper() if m else ""


def explorer_rows_for_country(base, selected_country):
    """
    All -> every E2E.
    DE  -> rows belonging to DE whose E2E code is DE or GT.
    AT  -> rows belonging to AT whose E2E code is AT or GT.
    etc.
    """
    if selected_country == "All":
        return base.copy()

    selected_country = str(selected_country).upper()
    rows = base[base["Country"].str.upper() == selected_country].copy()
    codes = rows["E2EName"].apply(extract_e2e_country_code)

    allowed = {selected_country} | GENERAL_E2E_CODES
    return rows[codes.isin(allowed)].copy()


# ============================================================
# NAME SIMILARITY
# ============================================================
def clean_e2e_name(name):
    if name is None:
        return ""
    s = str(name).strip()
    if not s:
        return ""

    if s.count("_") >= 4:
        return s.split("_", 4)[4].strip()

    prefix_regex = re.compile(
        r"^(?:\d{1,3}_)?(?:e2e(?:_[A-Za-z0-9]+)*)_",
        flags=re.IGNORECASE,
    )
    m = prefix_regex.match(s)
    if m:
        s = s[m.end():]
    return re.sub(r"^[\s_\-:]+", " ", s).strip()


def tokenize_name(value):
    if value is None:
        return []
    s = str(value).lower()
    s = re.sub(r"[^a-z0-9<>]+", " ", s)
    return [t for t in s.split() if t]


@lru_cache(maxsize=250000)
def _cached_name_similarity(a, b):
    ta = tokenize_name(a)
    tb = tokenize_name(b)

    if not ta and not tb:
        return 1.0
    if not ta or not tb:
        return 0.0

    matches = sum(1 for x, y in zip(ta, tb) if x == y)
    return matches / max(len(ta), len(tb))


def name_similarity(a, b):
    """
    Symmetric cached similarity.
    Sorting the two normalized strings means A/B and B/A share one cache entry.
    """
    a = "" if a is None else str(a)
    b = "" if b is None else str(b)
    if a <= b:
        return _cached_name_similarity(a, b)
    return _cached_name_similarity(b, a)

# ============================================================
# 1) E2E COMPARISON
# ============================================================
def build_e2e_comparisons(base):
    cols = ["Country", "E2EName"] + (["E2EID"] if "E2EID" in base.columns else [])
    e2es = base[cols].drop_duplicates().reset_index(drop=True)
    e2es["E2ECode"] = e2es["E2EName"].apply(extract_e2e_country_code)
    e2es["CleanedE2EName"] = e2es["E2EName"].apply(clean_e2e_name)

    records = e2es.to_dict("records")

    # Compute each cleaned-name similarity only once even when the same E2E
    # is present in several source-country records.
    cleaned_names = sorted(set(e2es["CleanedE2EName"].astype(str)))
    score_cache = {}

    for i, a in enumerate(cleaned_names):
        score_cache[(a, a)] = 1.0
        for b in cleaned_names[i + 1:]:
            key = (a, b) if a <= b else (b, a)
            score_cache[key] = name_similarity(a, b)

    same_rows = []
    cross_rows = []

    for i in range(len(records)):
        a = records[i]
        ca = a["CleanedE2EName"]
        country_a = str(a["Country"])

        for j in range(i + 1, len(records)):
            b = records[j]
            cb = b["CleanedE2EName"]
            key = (ca, cb) if ca <= cb else (cb, ca)
            score = score_cache.get(key, 0.0)

            country_b = str(b["Country"])
            same_country = country_a.lower() == country_b.lower()

            row = {
                "Country_A": country_a,
                "Country_B": country_b,
                "E2E_A": a["E2EName"],
                "E2E_B": b["E2EName"],
                "E2E_Code_A": a["E2ECode"],
                "E2E_Code_B": b["E2ECode"],
                "Cleaned_E2E_A": ca,
                "Cleaned_E2E_B": cb,
                "E2E_Similarity": round(score, 4),
                "E2E_Similarity_%": round(score * 100, 2),
                "Similar_E2E": score >= E2E_THRESHOLD,
                "ComparisonType": "Same country" if same_country else "Cross country",
            }

            if same_country:
                same_rows.append(row)
            else:
                cross_rows.append(row)

    same_df = pd.DataFrame(same_rows)
    cross_df = pd.DataFrame(cross_rows)

    if not same_df.empty:
        same_df.sort_values("E2E_Similarity", ascending=False, inplace=True)
        same_df.reset_index(drop=True, inplace=True)

    if not cross_df.empty:
        cross_df.sort_values("E2E_Similarity", ascending=False, inplace=True)
        cross_df.reset_index(drop=True, inplace=True)

    return e2es, same_df, cross_df

# ============================================================
# 2) TEST SET NAME COMPARISON
#    All comparisons are calculated internally for charts.
#    Only >=80% pairs are exposed in the detailed output.
# ============================================================
def build_testset_comparisons(base, same_e2e, cross_e2e):
    testsets = (
        base[["Country", "E2EName", "TestSetID", "TestSetName"]]
        .drop_duplicates()
        .reset_index(drop=True)
    )

    lookup = {}
    for (country, e2e), group in testsets.groupby(
        ["Country", "E2EName"], sort=False
    ):
        lookup[(country, e2e)] = list(
            group[["TestSetID", "TestSetName"]]
            .itertuples(index=False, name=None)
        )

    eligible_frames = []
    for df in (same_e2e, cross_e2e):
        if df is not None and not df.empty:
            eligible_frames.append(
                df.loc[df["E2E_Similarity"] >= E2E_THRESHOLD]
            )

    if not eligible_frames:
        return pd.DataFrame(), pd.DataFrame()

    eligible = pd.concat(eligible_frames, ignore_index=True)

    # Precompute similarities for only Test Set names that actually participate
    # in eligible E2E pairs.
    participating_names = set()

    for row in eligible.itertuples(index=False):
        sets_a = lookup.get((row.Country_A, row.E2E_A), ())
        sets_b = lookup.get((row.Country_B, row.E2E_B), ())
        participating_names.update(name for _, name in sets_a)
        participating_names.update(name for _, name in sets_b)

    participating_names = sorted(participating_names)
    ts_score_cache = {}

    # We do not calculate the full Cartesian set of all names here.
    # Scores are created lazily and reused across all eligible E2E pairs.
    def get_ts_score(a, b):
        key = (a, b) if a <= b else (b, a)
        score = ts_score_cache.get(key)
        if score is None:
            score = name_similarity(a, b)
            ts_score_cache[key] = score
        return score

    rows = []

    for row in eligible.itertuples(index=False):
        sets_a = lookup.get((row.Country_A, row.E2E_A), ())
        sets_b = lookup.get((row.Country_B, row.E2E_B), ())

        if not sets_a or not sets_b:
            continue

        for tsid_a, name_a in sets_a:
            for tsid_b, name_b in sets_b:
                score = get_ts_score(name_a, name_b)

                rows.append({
                    "ComparisonType": row.ComparisonType,
                    "Country_A": row.Country_A,
                    "Country_B": row.Country_B,
                    "E2E_A": row.E2E_A,
                    "E2E_B": row.E2E_B,
                    "E2E_Similarity": row.E2E_Similarity,
                    "E2E_Similarity_%": round(float(row.E2E_Similarity) * 100, 2),
                    "TestSetID_A": tsid_a,
                    "TestSetName_A": name_a,
                    "TestSetID_B": tsid_b,
                    "TestSetName_B": name_b,
                    "TestSet_Name_Similarity": round(score, 4),
                    "TestSet_Name_Similarity_%": round(score * 100, 2),
                    "Similar_TestSet": score >= TESTSET_THRESHOLD,
                })

    all_df = pd.DataFrame(rows)

    if all_df.empty:
        return all_df, all_df

    all_df.sort_values(
        ["E2E_Similarity", "TestSet_Name_Similarity"],
        ascending=[False, False],
        inplace=True,
    )
    all_df.reset_index(drop=True, inplace=True)

    similar_df = all_df.loc[
        all_df["TestSet_Name_Similarity"] >= TESTSET_THRESHOLD
    ].copy()
    similar_df.reset_index(drop=True, inplace=True)

    return all_df, similar_df

# ============================================================
# 3) TEST CASE COMPARISON BY TEST ID
#    Test cases are compared only inside >=80% Test Set pairs.
# ============================================================
def test_id_similarity(ids_a, ids_b):
    a = {str(x).strip() for x in ids_a if str(x).strip()}
    b = {str(x).strip() for x in ids_b if str(x).strip()}

    if not a and not b:
        return 1.0, set(), a, b
    if not a or not b:
        return 0.0, set(), a, b

    common = a & b
    return len(common) / max(len(a), len(b)), common, a, b


def build_testcase_comparison(base, similar_testsets):
    case_lookup = {
        (country, e2e, tsid, tsname): group[["TestID", "TestName"]].drop_duplicates()
        for (country, e2e, tsid, tsname), group in base.groupby(
            ["Country", "E2EName", "TestSetID", "TestSetName"], dropna=False
        )
    }

    summary_rows, detail_rows = [], []

    if similar_testsets is None or similar_testsets.empty:
        return pd.DataFrame(), pd.DataFrame()

    for _, row in similar_testsets.iterrows():
        key_a = (row["Country_A"], row["E2E_A"], row["TestSetID_A"], row["TestSetName_A"])
        key_b = (row["Country_B"], row["E2E_B"], row["TestSetID_B"], row["TestSetName_B"])

        ga = case_lookup.get(key_a, pd.DataFrame(columns=["TestID", "TestName"]))
        gb = case_lookup.get(key_b, pd.DataFrame(columns=["TestID", "TestName"]))

        score, common, set_a, set_b = test_id_similarity(
            ga["TestID"].tolist(),
            gb["TestID"].tolist(),
        )

        summary_rows.append({
            "ComparisonType": row["ComparisonType"],
            "Country_A": row["Country_A"],
            "Country_B": row["Country_B"],
            "E2E_A": row["E2E_A"],
            "E2E_B": row["E2E_B"],
            "E2E_Similarity_%": row["E2E_Similarity_%"],
            "TestSetID_A": row["TestSetID_A"],
            "TestSetName_A": row["TestSetName_A"],
            "TestSetID_B": row["TestSetID_B"],
            "TestSetName_B": row["TestSetName_B"],
            "TestSet_Name_Similarity_%": row["TestSet_Name_Similarity_%"],
            "Total_TestIDs_A": len(set_a),
            "Total_TestIDs_B": len(set_b),
            "Matching_TestIDs": len(common),
            "TestID_Similarity": round(score, 4),
            "TestID_Similarity_%": round(score * 100, 2),
        })

        names_a = (
            ga.groupby("TestID")["TestName"]
            .apply(lambda s: "; ".join(sorted({x for x in s if x})))
            .to_dict()
            if not ga.empty else {}
        )
        names_b = (
            gb.groupby("TestID")["TestName"]
            .apply(lambda s: "; ".join(sorted({x for x in s if x})))
            .to_dict()
            if not gb.empty else {}
        )

        for tid in sorted(set_a | set_b):
            if tid in set_a and tid in set_b:
                status = "Matched"
            elif tid in set_a:
                status = "Only in A"
            else:
                status = "Only in B"

            detail_rows.append({
                "ComparisonType": row["ComparisonType"],
                "Country_A": row["Country_A"],
                "Country_B": row["Country_B"],
                "E2E_A": row["E2E_A"],
                "E2E_B": row["E2E_B"],
                "TestSetID_A": row["TestSetID_A"],
                "TestSetName_A": row["TestSetName_A"],
                "TestSetID_B": row["TestSetID_B"],
                "TestSetName_B": row["TestSetName_B"],
                "TestID": tid,
                "TestName_A": names_a.get(tid, ""),
                "TestName_B": names_b.get(tid, ""),
                "MatchStatus": status,
                "TestID_Similarity_%": round(score * 100, 2),
            })

    summary_df = pd.DataFrame(summary_rows)
    detail_df = pd.DataFrame(detail_rows)

    if not summary_df.empty:
        summary_df = summary_df.sort_values(
            ["E2E_Similarity_%", "TestSet_Name_Similarity_%", "TestID_Similarity_%"],
            ascending=False,
        ).reset_index(drop=True)

    return summary_df, detail_df


# ============================================================
# ONE-TO-ONE MATCHING FOR LEVEL SUMMARY
# ============================================================
def greedy_unique_testset_matches(group):
    """
    Choose the highest-scoring >=80% Test Set pairs while ensuring
    each Test Set A and Test Set B is used only once.
    """
    if group is None or group.empty:
        return group.iloc[0:0] if group is not None else pd.DataFrame()

    ordered = group.sort_values("TestSet_Name_Similarity", ascending=False)
    used_a, used_b, selected = set(), set(), []

    for idx, row in ordered.iterrows():
        key_a = (row["Country_A"], row["E2E_A"], row["TestSetID_A"], row["TestSetName_A"])
        key_b = (row["Country_B"], row["E2E_B"], row["TestSetID_B"], row["TestSetName_B"])

        if key_a in used_a or key_b in used_b:
            continue

        used_a.add(key_a)
        used_b.add(key_b)
        selected.append(idx)

    return ordered.loc[selected].copy() if selected else ordered.iloc[0:0].copy()


def build_level_summary(base, same_e2e, cross_e2e, similar_testsets, testcase_summary):
    pair_frames = [
        df for df in (same_e2e, cross_e2e)
        if df is not None and not df.empty
    ]

    columns = [
        "E2E",
        "Comparing E2E",
        "E2E Naming level similarity score",
        "Test Set level similarity score",
        "Test case level similarity score",
        "Test Requirement level similarity score",
        "Test Data Requirement level similarity score",
    ]

    if not pair_frames:
        return pd.DataFrame(columns=columns)

    pairs = pd.concat(pair_frames, ignore_index=True)

    set_counts = (
        base[["Country", "E2EName", "TestSetID", "TestSetName"]]
        .drop_duplicates()
        .groupby(["Country", "E2EName"], sort=False)
        .size()
        .to_dict()
    )

    # Group similar test sets ONCE by E2E pair.
    grouped_testsets = {}
    if similar_testsets is not None and not similar_testsets.empty:
        group_cols = [
            "ComparisonType",
            "Country_A",
            "Country_B",
            "E2E_A",
            "E2E_B",
        ]
        for key, group in similar_testsets.groupby(group_cols, sort=False):
            grouped_testsets[key] = group

    # Test-case summary lookup ONCE.
    tc_lookup = {}
    if testcase_summary is not None and not testcase_summary.empty:
        for r in testcase_summary.itertuples(index=False):
            key = (
                r.ComparisonType,
                r.Country_A,
                r.Country_B,
                r.E2E_A,
                r.E2E_B,
                r.TestSetID_A,
                r.TestSetName_A,
                r.TestSetID_B,
                r.TestSetName_B,
            )
            tc_lookup[key] = (
                int(r.Matching_TestIDs),
                int(r.Total_TestIDs_A),
                int(r.Total_TestIDs_B),
            )

    # Precompute qualifying pair metrics ONCE.
    pair_metrics = {}

    for key, group in grouped_testsets.items():
        comparison_type, country_a, country_b, e2e_a, e2e_b = key

        matched = greedy_unique_testset_matches(group)

        total_a = set_counts.get((country_a, e2e_a), 0)
        total_b = set_counts.get((country_b, e2e_b), 0)
        denom_sets = max(total_a, total_b)

        testset_score = (
            len(matched) / denom_sets
            if denom_sets > 0
            else 0.0
        )

        matching_ids = 0
        total_ids_a = 0
        total_ids_b = 0

        for r in matched.itertuples(index=False):
            tc_key = (
                r.ComparisonType,
                r.Country_A,
                r.Country_B,
                r.E2E_A,
                r.E2E_B,
                r.TestSetID_A,
                r.TestSetName_A,
                r.TestSetID_B,
                r.TestSetName_B,
            )

            values = tc_lookup.get(tc_key)
            if values is not None:
                m, a_total, b_total = values
                matching_ids += m
                total_ids_a += a_total
                total_ids_b += b_total

        denom_cases = max(total_ids_a, total_ids_b)
        testcase_score = (
            matching_ids / denom_cases
            if denom_cases > 0
            else 0.0
        )

        pair_metrics[key] = (
            round(testset_score * 100, 2),
            round(testcase_score * 100, 2),
        )

    # Now build rows cheaply.
    result_rows = []

    for r in pairs.itertuples(index=False):
        key = (
            r.ComparisonType,
            r.Country_A,
            r.Country_B,
            r.E2E_A,
            r.E2E_B,
        )

        testset_level, testcase_level = pair_metrics.get(key, ("", ""))

        result_rows.append({
            "E2E": r.E2E_A,
            "Comparing E2E": r.E2E_B,
            "E2E Naming level similarity score": round(float(r.E2E_Similarity) * 100, 2),
            "Test Set level similarity score": testset_level,
            "Test case level similarity score": testcase_level,
            "Test Requirement level similarity score": "",
            "Test Data Requirement level similarity score": "",
        })

    return pd.DataFrame(result_rows, columns=columns)

# ============================================================
# SUMMARY / DASHBOARD STATS / TIME SAVED
# ============================================================
def build_summary(base, same_e2e, cross_e2e, all_testsets, similar_testsets, testcase_summary, testcase_detail):
    # ------------------------------------------------------------
    # Same-country UNIQUE similarity sets (not pairwise counts)
    # ------------------------------------------------------------
    same_e2e_similar = (
        same_e2e[same_e2e["E2E_Similarity"] >= E2E_THRESHOLD].copy()
        if same_e2e is not None and not same_e2e.empty
        else pd.DataFrame()
    )

    same_testset_similar = (
        similar_testsets[similar_testsets["ComparisonType"] == "Same country"].copy()
        if similar_testsets is not None and not similar_testsets.empty
        else pd.DataFrame()
    )

    same_case_matched = (
        testcase_detail[
            (testcase_detail["ComparisonType"] == "Same country")
            & (testcase_detail["MatchStatus"] == "Matched")
        ].copy()
        if testcase_detail is not None and not testcase_detail.empty
        else pd.DataFrame()
    )

    countries = sorted(base["Country"].dropna().astype(str).unique().tolist())

    def keys_from_two_sides(df, a_cols, b_cols):
        if df is None or df.empty:
            return set()
        keys = set()
        for _, r in df.iterrows():
            keys.add(tuple(str(r[c]) for c in a_cols))
            keys.add(tuple(str(r[c]) for c in b_cols))
        return keys

    rows = []

    for country in ["All"] + countries:
        if country == "All":
            b = base.copy()
            e2e_match = same_e2e_similar
            ts_match = same_testset_similar
            tc_match = same_case_matched
        else:
            b = base[base["Country"] == country].copy()
            e2e_match = (
                same_e2e_similar[same_e2e_similar["Country_A"] == country]
                if not same_e2e_similar.empty else same_e2e_similar
            )
            ts_match = (
                same_testset_similar[same_testset_similar["Country_A"] == country]
                if not same_testset_similar.empty else same_testset_similar
            )
            tc_match = (
                same_case_matched[same_case_matched["Country_A"] == country]
                if not same_case_matched.empty else same_case_matched
            )

        total_e2e_keys = set(
            tuple(x)
            for x in b[["Country", "E2EName"]].drop_duplicates().astype(str).to_numpy()
        )
        similar_e2e_keys = keys_from_two_sides(
            e2e_match,
            ["Country_A", "E2E_A"],
            ["Country_B", "E2E_B"],
        )

        total_ts_keys = set(
            tuple(x)
            for x in b[["Country", "E2EName", "TestSetID", "TestSetName"]]
            .drop_duplicates()
            .astype(str)
            .to_numpy()
        )
        similar_ts_keys = keys_from_two_sides(
            ts_match,
            ["Country_A", "E2E_A", "TestSetID_A", "TestSetName_A"],
            ["Country_B", "E2E_B", "TestSetID_B", "TestSetName_B"],
        )

        total_tc_keys = set(
            tuple(x)
            for x in b[["Country", "E2EName", "TestSetID", "TestID"]]
            .drop_duplicates()
            .astype(str)
            .to_numpy()
        )
        similar_tc_keys = keys_from_two_sides(
            tc_match,
            ["Country_A", "E2E_A", "TestSetID_A", "TestID"],
            ["Country_B", "E2E_B", "TestSetID_B", "TestID"],
        )

        rows.extend([
            {
                "Country": country,
                "Level": "E2E",
                "Total_Unique": len(total_e2e_keys),
                "Similar_Unique": len(similar_e2e_keys),
                "Other_Unique": max(len(total_e2e_keys) - len(similar_e2e_keys), 0),
            },
            {
                "Country": country,
                "Level": "Test Set",
                "Total_Unique": len(total_ts_keys),
                "Similar_Unique": len(similar_ts_keys),
                "Other_Unique": max(len(total_ts_keys) - len(similar_ts_keys), 0),
            },
            {
                "Country": country,
                "Level": "Test Case",
                "Total_Unique": len(total_tc_keys),
                "Similar_Unique": len(similar_tc_keys),
                "Other_Unique": max(len(total_tc_keys) - len(similar_tc_keys), 0),
            },
        ])

    unique_chart_data = pd.DataFrame(rows)

    # ------------------------------------------------------------
    # Time saved: only UNIQUE matched B-side Test Cases from
    # SAME-COUNTRY comparisons, so repeated pairwise appearances
    # cannot inflate the saving.
    # ------------------------------------------------------------
    if same_case_matched.empty:
        eliminable_all = 0
    else:
        eliminable_all = (
            same_case_matched[
                ["Country_B", "E2E_B", "TestSetID_B", "TestID"]
            ]
            .drop_duplicates()
            .shape[0]
        )

    working_days_saved = eliminable_all / CASES_PER_WORKING_DAY
    hours_saved = working_days_saved * HOURS_PER_WORKING_DAY

    all_e2e_row = unique_chart_data[
        (unique_chart_data["Country"] == "All")
        & (unique_chart_data["Level"] == "E2E")
    ].iloc[0]
    all_ts_row = unique_chart_data[
        (unique_chart_data["Country"] == "All")
        & (unique_chart_data["Level"] == "Test Set")
    ].iloc[0]
    all_tc_row = unique_chart_data[
        (unique_chart_data["Country"] == "All")
        & (unique_chart_data["Level"] == "Test Case")
    ].iloc[0]

    overall = pd.DataFrame([
        ("Input rows", len(base)),
        ("Countries", base["Country"].nunique()),
        ("Total unique E2Es", int(all_e2e_row["Total_Unique"])),
        ("Similar unique E2Es - same country >=80%", int(all_e2e_row["Similar_Unique"])),
        ("Total unique Test Sets", int(all_ts_row["Total_Unique"])),
        ("Similar unique Test Sets - same country >=80%", int(all_ts_row["Similar_Unique"])),
        ("Total unique Test Cases", int(all_tc_row["Total_Unique"])),
        ("Similar unique Test Cases - same country", int(all_tc_row["Similar_Unique"])),
        ("Potentially eliminable unique Test Cases - same country", eliminable_all),
        ("Estimated working days saved", round(working_days_saved, 2)),
        ("Estimated hours saved", round(hours_saved, 2)),
    ], columns=["Metric", "Value"])

    by_country = (
        base.groupby("Country")
        .agg(
            Input_Rows=("E2EName", "size"),
            Unique_E2Es=("E2EName", "nunique"),
            Unique_TestSets=("TestSetID", "nunique"),
            Unique_TestIDs=("TestID", "nunique"),
        )
        .reset_index()
        .sort_values("Country")
    )

    time_rows = []
    for country in ["All"] + countries:
        if country == "All":
            matched = same_case_matched
            total_cases = int(all_tc_row["Total_Unique"])
        else:
            matched = (
                same_case_matched[same_case_matched["Country_B"] == country]
                if not same_case_matched.empty else same_case_matched
            )
            total_cases = int(
                unique_chart_data[
                    (unique_chart_data["Country"] == country)
                    & (unique_chart_data["Level"] == "Test Case")
                ]["Total_Unique"].iloc[0]
            )

        eliminable = (
            matched[["Country_B", "E2E_B", "TestSetID_B", "TestID"]]
            .drop_duplicates()
            .shape[0]
            if matched is not None and not matched.empty
            else 0
        )
        days = eliminable / CASES_PER_WORKING_DAY
        hours = days * HOURS_PER_WORKING_DAY

        time_rows.append({
            "Country": country,
            "Total_Unique_Test_Cases": total_cases,
            "Potentially_Eliminable_Unique_Test_Cases": eliminable,
            "Manual_Capacity_Test_Cases_Per_Day": CASES_PER_WORKING_DAY,
            "Working_Hours_Per_Day": HOURS_PER_WORKING_DAY,
            "Working_Days_Saved": round(days, 2),
            "Hours_Saved": round(hours, 2),
            "Calculation": (
                f"{eliminable} unique eliminable test cases / "
                f"{CASES_PER_WORKING_DAY} per day * "
                f"{HOURS_PER_WORKING_DAY} hours = {hours:.2f} hours saved"
            ),
        })

    time_saved = pd.DataFrame(time_rows)

    return overall, by_country, unique_chart_data, time_saved

# ============================================================
# FULL PROCESS
# ============================================================
def process_dataframe(df_raw):
    base = standardize_input(df_raw)

    e2e_unique, same_e2e, cross_e2e = build_e2e_comparisons(base)

    all_testsets, similar_testsets = build_testset_comparisons(
        base, same_e2e, cross_e2e
    )

    testcase_summary, testcase_detail = build_testcase_comparison(
        base, similar_testsets
    )

    level_summary = build_level_summary(
        base, same_e2e, cross_e2e, similar_testsets, testcase_summary
    )

    summary_overall, summary_country, chart_data, time_saved = build_summary(
        base,
        same_e2e,
        cross_e2e,
        all_testsets,
        similar_testsets,
        testcase_summary,
        testcase_detail,
    )

    return {
        "base": base,
        "e2e_unique": e2e_unique,
        "same_e2e": same_e2e,
        "cross_e2e": cross_e2e,
        "all_testsets": all_testsets,
        "similar_testsets": similar_testsets,
        "testcase_summary": testcase_summary,
        "testcase_detail": testcase_detail,
        "level_summary": level_summary,
        "summary_overall": summary_overall,
        "summary_country": summary_country,
        "chart_data": chart_data,
        "time_saved": time_saved,
    }


