def make_excel_output(result):
    out = BytesIO()

    with pd.ExcelWriter(out, engine="xlsxwriter") as writer:
        wb = writer.book

        red = "#E30613"
        orange = "#F28C00"
        orange_dark = "#D96F00"
        yellow = "#FFD500"
        blue = "#0050AA"
        white = "#FFFFFF"

        title_fmt = wb.add_format({
            "bold": True,
            "font_color": white,
            "bg_color": orange_dark,
            "font_size": 14,
            "align": "center",
            "valign": "vcenter",
        })

        header_fmt = wb.add_format({
            "bold": True,
            "font_color": white,
            "bg_color": orange,
            "border": 1,
            "border_color": white,
            "align": "center",
            "valign": "vcenter",
            "text_wrap": True,
        })

        orange_header = wb.add_format({
            "bold": True,
            "font_color": white,
            "bg_color": orange_dark,
            "border": 1,
            "border_color": white,
            "align": "center",
            "valign": "vcenter",
            "text_wrap": True,
        })

        # ========================================================
        # 1. SUMMARY
        # ========================================================
        result["summary_overall"].to_excel(
            writer,
            sheet_name="SUMMARY",
            index=False,
            startrow=2,
        )

        summary_country_start = len(result["summary_overall"]) + 7
        result["summary_country"].to_excel(
            writer,
            sheet_name="SUMMARY",
            index=False,
            startrow=summary_country_start,
        )

        ws = writer.sheets["SUMMARY"]
        ws.merge_range("A1:D2", "SMART REGRESSION SUMMARY", title_fmt)
        ws.set_column("A:A", 48)
        ws.set_column("B:E", 22)
        ws.freeze_panes(3, 0)

        # ========================================================
        # 2. LEVEL_SUMMARY
        # ========================================================
        result["level_summary"].to_excel(
            writer,
            sheet_name="LEVEL_SUMMARY",
            index=False,
        )

        ws = writer.sheets["LEVEL_SUMMARY"]
        for col_num, value in enumerate(result["level_summary"].columns):
            ws.write(
                0,
                col_num,
                value,
                orange_header if col_num >= 5 else header_fmt,
            )

        ws.freeze_panes(1, 0)
        if len(result["level_summary"].columns) > 0:
            ws.autofilter(
                0,
                0,
                max(0, len(result["level_summary"])),
                len(result["level_summary"].columns) - 1,
            )

        ws.set_column(0, 1, 44)
        ws.set_column(2, 6, 30)

        # ========================================================
        # 3. DASHBOARD WITH UNIQUE SAME-COUNTRY CHARTS
        # ========================================================
        dash = wb.add_worksheet("DASHBOARD")
        writer.sheets["DASHBOARD"] = dash

        dash.merge_range("A1:J2", "SMART REGRESSION DASHBOARD", title_fmt)

        all_stats = result["chart_data"][
            result["chart_data"]["Country"] == "All"
        ].reset_index(drop=True)

        dash.write("A4", "Level", orange_header)
        dash.write("B4", "Total Unique", orange_header)
        dash.write("C4", "Similar Unique", orange_header)
        dash.write("D4", "Other Unique", orange_header)

        for i, r in all_stats.iterrows():
            row = i + 4
            dash.write(row, 0, r["Level"])
            dash.write_number(row, 1, float(r["Total_Unique"]))
            dash.write_number(row, 2, float(r["Similar_Unique"]))
            dash.write_number(row, 3, float(r["Other_Unique"]))

        # Time-saved summary
        ts_all = result["time_saved"][
            result["time_saved"]["Country"] == "All"
        ].iloc[0].to_dict()

        dash.write("F4", "Time Saved", orange_header)
